import axios from '../api/axios';
import React, {useEffect, useState, useContext, useRef} from 'react'
import { Button } from 'react-bootstrap';
import { booleanContext } from '../Context';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import Register from './Register';
import Popup from 'reactjs-popup';



const LOGIN_URL = '/user/auth/login/';

function Login() {
    const{isLoggedIn, setIsLoggedIn} =useContext(booleanContext)
    const navigate = useNavigate();
    const location = useLocation();
    const from = location.state?.from?.pathname || "/";
    const[p, setP]  =useState(false)
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [errMsg, setErrMsg] = useState('');
    const [seen, setSeen] = useState(false)

    const url = `${LOGIN_URL}?username=${username}&password=${password}`

    useEffect(() => {
      setErrMsg('');
  }, [username, password])
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
        const response = await axios.post(url);
  console.log(response);
  const accessToken = response?.data?.access_token;
  const refreshToken = response?.data?.refresh_token;

  const roles = response?.data?.authorities;
  console.log(response.data.authorities);
  localStorage.setItem("Authorities", roles);
  localStorage.setItem("Refresh Token", refreshToken);
  localStorage.setItem("Access Token", accessToken);
  localStorage.setItem("username", username);
  localStorage.setItem("password", password);
  localStorage.setItem("role", roles);

  setIsLoggedIn(true)


  alert("Login Successful");
  navigate(from, { replace: true });

    } catch (err) {
  alert("error with login")
  console.log(err);
        if (!err?.response) {

            setErrMsg('No Server Response');
        } else if (err.response?.status === 400) {
            setErrMsg('Missing Username or Password');
        } else if (err.response?.status === 401) {
            setErrMsg('Unauthorized');
        } else {
            setErrMsg('Login Failed');
        }
        // errRef.current.focus();
    }
  }

  function togglePop () {
      setSeen(!seen);
  };

const popup =()=>{
    return(
        <>

          <Register />

        </>
    )
}



    return (
   <>
   <h1>JT's Messenger</h1>
   <p>Connect with friends and the world around you on JT's Messenger.</p>
  <section>
              {/* <p ref={errRef} className={errMsg ? "errmsg" : "offscreen"} aria-live="assertive">{errMsg}</p> */}
              <h1>Sign In</h1>
              <form>
                  <label htmlFor="username">Username:</label>
                  <input
                      type="text"
                      id="username"
                      // ref={userRef}
                      autoComplete="off"
                      onChange={(e) => setUsername(e.target.value)}
                      value={username}
                      required
                  />

                  <label htmlFor="password">Password:</label>
                  <input
                      type="password"
                      id="password"
                      onChange={(e) => setPassword(e.target.value)}
                      value={password}
                      required
                  />
                  <Button onClick={handleSubmit}>Login</Button>
              </form>
              <p>
              <span className="line">
                    <Link to="/forgot">Forgot Your Password?</Link>
                </span>
              <br/>
              <br/>


                  <span className="line">

                  </span>
              </p>
          </section>
       Need an Account?<br />
            <Popup trigger=
                {<Button>Create a New Account</Button> }
               position="center"
                >
            {popup}
            </Popup>  
   </>
    );
}

export default Login;
